import { cn } from "./lib/utils";

// Base64-embedded copies of the 256px PNG renders of bookings-icon-studios'
// public/{google,apple,facebook}.svg — same embedding pattern as
// logoAssets.ts. Rasterized rather than kept as inline vector: facebook.svg
// in particular is a fragile svg-in-svg-in-base64-PNG export (from
// svgrepo.com) that is not worth reproducing faithfully as JSX, and a flat
// PNG guarantees pixel-identical output to the web app for all three.
//
// The apple source glyph is white-on-transparent (built for a dark
// background), so it is inverted by default to render black in light mode,
// and un-inverted in dark mode to show its native white — the opposite of
// google/facebook, which are full-color and render as-is in both themes.

const GOOGLE_ICON_PNG = "data:image/png;base64,";
const APPLE_ICON_PNG = "data:image/png;base64,";
const FACEBOOK_ICON_PNG = "data:image/png;base64,";

export function GoogleIcon({ className, ...props }: React.ImgHTMLAttributes<HTMLImageElement>) {
  return (
    <img
      src={GOOGLE_ICON_PNG}
      alt=""
      className={cn("object-contain", className)}
      {...props}
    />
  );
}

export function AppleIcon({ className, ...props }: React.ImgHTMLAttributes<HTMLImageElement>) {
  return (
    <img
      src={APPLE_ICON_PNG}
      alt=""
      className={cn("object-contain invert dark:invert-0", className)}
      {...props}
    />
  );
}

export function FacebookIcon({ className, ...props }: React.ImgHTMLAttributes<HTMLImageElement>) {
  return (
    <img
      src={FACEBOOK_ICON_PNG}
      alt=""
      className={cn("object-contain", className)}
      {...props}
    />
  );
}
